messages.content:
I'll add the 'reviewed' label.

```json
{
  "intent": "add_label",
  "requires_confirmation": false,
  "actions": [
    {
      "op": "INSERT",
      "table": "board_labels",
      "values": {
        "id": "{{generate_uuid}}",
        "board_id": ":current_board_id",
        "label": "reviewed",
        "created_at": "{{now}}"
      },
      "on_conflict": "ignore"
    }
  ]
}
```

```sql
SELECT o.id, o.name, COUNT(nc.id) as cell_count FROM objects o JOIN notebook_cells nc ON nc.board_id = o.id WHERE o.board_mode = 'notebook' GROUP BY o.id ORDER BY cell_count DESC LIMIT 10;
```

I'll create the Operations group with an icon.

```json
{
  "intent": "create_group",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "INSERT",
      "table": "groups",
      "values": {
        "id": "{{generate_uuid}}",
        "name": "Operations",
        "icon": "🔧",
        "created_at": "{{now}}"
      }
    }
  ],
  "confirmation": "Create group 'Operations' with 🔧 icon?"
}
```

```sql
SELECT DISTINCT label FROM board_labels ORDER BY label;
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN notebook_cells nc ON nc.board_id = o.id WHERE nc.cell_type = 'image' AND o.archived = 0;
```

```sql
SELECT w.name, g.name as group_name, COUNT(o.id) as board_count FROM workspaces w JOIN groups g ON w.group_id = g.id LEFT JOIN objects o ON o.workspace_id = w.id AND o.type = 'whiteboard' GROUP BY w.id ORDER BY board_count DESC;
```

```sql
SELECT o.id, o.name, o.board_mode FROM objects o JOIN workspaces w ON o.workspace_id = w.id WHERE w.name = 'API Docs' AND o.type = 'whiteboard' AND o.archived = 0;
```

```sql
SELECT o.id, o.name, w.name as workspace FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Design' AND o.archived = 0;
```

I'll unstar this board.

```json
{
  "intent": "unstar",
  "requires_confirmation": false,
  "actions": [
    {
      "op": "UPDATE",
      "table": "board_metadata",
      "set": {"starred": 0},
      "where": {"board_id": ":current_board_id"}
    }
  ]
}
```

I'll create the workspace and initial board.

```json
{
  "intent": "create_workspace_with_content",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Find Product group",
      "sql": "SELECT id FROM groups WHERE name = 'Product'"
    },
    {
      "op": "INSERT",
      "table": "workspaces",
      "values": {
        "id": "{{generate_uuid}}",
        "group_id": "{{result[0].id}}",
        "name": "Q2 Planning",
        "created_at": "{{now}}"
      },
      "save_as": "new_workspace"
    },
    {
      "op": "INSERT",
      "table": "objects",
      "values": {
        "id": "{{generate_uuid}}",
        "workspace_id": "{{new_workspace.id}}",
        "type": "whiteboard",
        "name": "Roadmap",
        "board_mode": "notebook",
        "created_at": "{{now}}"
      }
    }
  ],
  "confirmation": "Create workspace 'Q2 Planning' in Product with a 'Roadmap' board?"
}
```

```sql
SELECT o.id, o.name FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Design' AND o.type = 'file';
```

I'll delete the test workspace. This requires confirmation.

```json
{
  "intent": "delete_workspace",
  "requires_confirmation": true,
  "requires_empty_check": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Check if workspace is empty",
      "sql": "SELECT COUNT(*) as count FROM objects WHERE workspace_id = (SELECT id FROM workspaces WHERE name = 'test')"
    },
    {
      "op": "DELETE",
      "table": "workspaces",
      "where": {"name": "test"},
      "condition": "{{result[0].count}} == 0"
    }
  ],
  "confirmation": "Delete workspace 'test'? This cannot be undone."
}
```

I'll mark this board as a template.

```json
{
  "intent": "set_template",
  "requires_confirmation": false,
  "actions": [
    {
      "op": "UPSERT",
      "table": "board_metadata",
      "values": {"board_id": ":current_board_id", "template": 1},
      "on_conflict": {"update": {"template": 1}}
    }
  ]
}
```

I'll move this board to a Marketing workspace.

```json
{
  "intent": "move",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Find Marketing workspace",
      "sql": "SELECT w.id FROM workspaces w JOIN groups g ON w.group_id = g.id WHERE g.name = 'Marketing' LIMIT 1"
    },
    {
      "op": "UPDATE",
      "table": "objects",
      "set": {"workspace_id": "{{result[0].id}}", "updated_at": "{{now}}"},
      "where": {"id": ":current_board_id"}
    }
  ],
  "confirmation": "Move this board to Marketing?"
}
```

I'll remove all labels from this board.

```json
{
  "intent": "clear_labels",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "DELETE",
      "table": "board_labels",
      "where": {"board_id": ":current_board_id"}
    }
  ],
  "confirmation": "Remove all labels from this board?"
}
```
